package ca.yorku.eecs3311.coursepilot.domain.repository;
import ca.yorku.eecs3311.coursepilot.domain.model.QuizAttempt; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface QuizAttemptRepository extends JpaRepository<QuizAttempt,Long>{ @Query("select a from QuizAttempt a join fetch a.quiz q where q.course.id=:courseId order by a.id asc") List<QuizAttempt> findByCourseId(@Param("courseId")Long courseId); @Query("select a from QuizAttempt a where a.quiz.id=:quizId") List<QuizAttempt> findByQuizId(@Param("quizId")Long quizId); @Query("select distinct a from QuizAttempt a join fetch a.quiz q left join fetch a.responses r left join fetch r.question where a.id=:attemptId and q.id=:quizId and q.course.id=:courseId") Optional<QuizAttempt> findOwned(@Param("attemptId")Long attemptId,@Param("quizId")Long quizId,@Param("courseId")Long courseId); }
